package Tv2.Controller;
import Tv2.View.TiepNhanPage;import MainPage.Controller.PageTasks;import MainPage.View.Workspace;import Model.*;import Service.*;import java.time.*;import java.util.*;import java.awt.Component;
public class TiepNhanController {
 public static void open(Component owner,int b,boolean direct,Runnable done){PageTasks.run(owner,()->{List<Workspace.Choice> c=new ArrayList<>();c.add(new Workspace.Choice(0,"Chưa chọn"));new DanhMucService().getByNhomDanhMuc(b,"KHOA_HOC").stream().filter(DanhMucModel::isTrangThai).forEach(x->c.add(new Workspace.Choice(x.getMaDanhMuc(),x.getTenDanhMuc())));return c;},c->{var i=TiepNhanPage.show(owner,c.toArray(Workspace.Choice[]::new),direct);if(i==null)return;if(!i.phone().isBlank()&&!i.phone().replaceAll("[ +()-]", "").matches("[0-9]{9,15}")){Workspace.message(owner,"Số điện thoại không hợp lệ");return;}if(!i.email().isBlank()&&!i.email().trim().matches("[^@\\s]+@[^@\\s]+\\.[^@\\s]+")){Workspace.message(owner,"Email không hợp lệ");return;}if(i.name().isBlank()){Workspace.message(owner,"Họ tên không được trống");return;}LocalDate birth;try{birth=i.birth().isBlank()?null:LocalDate.parse(i.birth().trim());if(birth!=null&&birth.isAfter(LocalDate.now()))throw new IllegalArgumentException("Ngày sinh không hợp lệ");}catch(Exception e){Workspace.message(owner,e.getMessage());return;}PageTasks.actor(owner,b,actor->PageTasks.run(owner,()->{HocVienModel h=new HocVienModel();h.setMaHoSo("HV-"+UUID.randomUUID().toString().substring(0,16));h.setHoTen(i.name().trim());h.setNgaySinh(birth);h.setGioiTinh(blank(i.gender()));h.setTenPhuHuynh(blank(i.parent()));h.setSoDienThoai(blank(i.phone()));h.setEmail(blank(i.email()));h.setDiaChi(blank(i.address()));h.setGhiChu(blank(i.note()));h.setMaNguoiTao(actor);h.setMaNguoiTuVan(actor);h.setTrangThai(direct?"CHINH_THUC":"TIEP_NHAN");if(direct)h.setNgayChinhThuc(LocalDate.now());PageTasks.require(new HocVienService().insert(b,h),"Không lưu được hồ sơ");if(!direct){TuongTacHocVienModel t=new TuongTacHocVienModel();t.setMaHocVien(h.getMaHocVien());t.setMaNhanSu(actor);t.setLoaiTuongTac("TIEP_NHAN");t.setMaKhoaHocMongMuon(i.course()==0?null:i.course());t.setThoiGianMongMuon(blank(i.desired()));t.setNoiDung(blank(i.note()));PageTasks.require(new TuongTacHocVienService().insert(b,t),"Hồ sơ #"+h.getMaHocVien()+" đã lưu, nhưng chưa lưu được nguyện vọng; kiểm tra Hệ thống trước khi thử lại");}return h.getMaHocVien();},id->{done.run();if(i.next()){if(direct)XepLopController.open(owner,b,id,done);else HocThuController.open(owner,b,id,i.course()==0?null:i.course(),done);}}));});}
 static String blank(String s){return s==null||s.isBlank()?null:s.trim();}
}
